from marqov import task, workflow


@task(timeout=60)
def alice(seed: int):
    values = [seed, seed + 1, seed + 2]
    return {"stage": "alice", "seed": seed, "values": values, "total": sum(values)}


@workflow
def native_canary(seed: int = 7):
    return {"schema_version": 1, "alice": alice(seed)}
